UPDATE user_device
SET last_active_time = #{lastActiveTime}, status = 1
WHERE id = #{id}

UPDATE user_device
SET status = #{status}
WHERE id = #{id}

UPDATE user_device
SET trusted = #{trusted}
WHERE id = #{id}

UPDATE user_device
SET status = 0
WHERE user_id = #{userId}

    AND device_id != #{excludeDeviceId}
